-- New Zealand deep-dive page translations: page fields, stats, cards, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol descentralizado de 4 esquinas', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las Reglas de Contratación Pública, los umbrales para grandes proveedores y cualquier futura extensión a un B2B más amplio siguen sujetos a cambios — confirme los requisitos actuales directamente con el MBIE antes de construir una integración.', 'El enfoque de Nueva Zelanda está impulsado por reglas de contratación pública, no por la legislación fiscal — las obligaciones residen en las Reglas de Contratación Pública, no en la legislación de IVA/GST.', 'Especificación idéntica a la de Australia — un estándar genuinamente trans-Tasmania, no una variante nacional parecida.', 'Un modelo Peppol puro de cuatro esquinas — sin plataforma gubernamental central, sin paso de compensación, idéntico en estructura al de Australia.', 'Si es un gran proveedor del gobierno, el plazo de 2027 está más cerca de lo que parece una vez que se tiene en cuenta el tiempo de pruebas con organismos individuales.', 'La economía B2B de Nueva Zelanda sigue siendo voluntaria — pero la cadena de suministro gubernamental cada vez lo será menos.' FROM countries WHERE name_en = 'New Zealand';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dezentrales 4-Corner-Peppol-Modell', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Government Procurement Rules, Schwellenwerte für Großlieferanten und jede künftige Ausweitung auf breiteres B2B bleiben Änderungen unterworfen — bestätigen Sie aktuelle Anforderungen direkt beim MBIE, bevor Sie eine Integration aufbauen.', 'Neuseelands Ansatz ist beschaffungsregelbasiert statt steuerrechtlich getrieben — die Pflichten sind in den Government Procurement Rules verankert, nicht in der Umsatzsteuer-/GST-Gesetzgebung.', 'Identische Spezifikation wie Australien — ein echter trans-tasmanischer Standard, keine ähnlich klingende nationale Variante.', 'Ein reines Vier-Ecken-Peppol-Modell — keine zentrale Regierungsplattform, kein Clearing-Schritt, strukturell identisch mit dem Australiens.', 'Wenn Sie ein Großlieferant der Regierung sind, ist die Frist 2027 näher, als sie aussieht, sobald man die Testzeit mit einzelnen Behörden einrechnet.', 'Neuseelands B2B-Wirtschaft bleibt freiwillig — aber die staatliche Lieferkette zunehmend nicht mehr.' FROM countries WHERE name_en = 'New Zealand';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Modèle Peppol décentralisé à 4 coins', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les règles de passation des marchés publics, les seuils applicables aux grands fournisseurs et toute future extension à un B2B plus large restent sujets à modification — confirmez les exigences actuelles directement auprès du MBIE avant de construire une intégration.', 'L''approche néo-zélandaise est guidée par les règles de passation des marchés plutôt que par le droit fiscal — les obligations résident dans les règles de passation des marchés publics, non dans la législation TVA/GST.', 'Spécification identique à celle de l''Australie — une norme véritablement trans-tasmanienne, et non une variante nationale qui y ressemble.', 'Un modèle Peppol à quatre coins pur — pas de plateforme gouvernementale centrale, pas d''étape de contrôle, identique en structure à celui de l''Australie.', 'Si vous êtes un grand fournisseur du gouvernement, l''échéance de 2027 est plus proche qu''il n''y paraît une fois pris en compte le temps de test avec chaque organisme.', 'L''économie B2B néo-zélandaise reste volontaire — mais la chaîne d''approvisionnement gouvernementale de moins en moins.' FROM countries WHERE name_en = 'New Zealand';

