INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Especificación', '[["Formato", "PINT A-NZ (versión adaptada de Nueva Zelanda de EN 16931)"], ["Sintaxis", "XML basado en UBL"], ["Reemplazada", "Peppol BIS Billing 3.0 (obsoleta desde mayo de 2025)"]]', 'Dado que Australia y Nueva Zelanda comparten esta especificación exacta, una empresa que opera en ambos mercados puede reutilizar las mismas asignaciones y validaciones en lugar de construir dos veces.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Spezifikation', '[["Format", "PINT A-NZ (Neuseelands angepasste Version von EN 16931)"], ["Syntax", "UBL-basiertes XML"], ["Abgelöst", "Peppol BIS Billing 3.0 (veraltet seit Mai 2025)"]]', 'Da Australien und Neuseeland genau diese Spezifikation teilen, kann ein Unternehmen, das in beiden Märkten tätig ist, dieselben Mappings und Validierungen wiederverwenden, statt zweimal zu bauen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Spécification', '[["Format", "PINT A-NZ (version néo-zélandaise adaptée de la norme EN 16931)"], ["Syntaxe", "XML basé sur UBL"], ["Remplacée", "Peppol BIS Billing 3.0 (obsolète depuis mai 2025)"]]', 'Comme l''Australie et la Nouvelle-Zélande partagent exactement cette spécification, une entreprise opérant sur les deux marchés peut réutiliser les mêmes mappages et validations plutôt que de construire deux fois.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificadores', '[["Identificador de enrutamiento", "New Zealand Business Number (NZBN)"], ["Función", "Identificador de participante Peppol"]]', 'Toda empresa neozelandesa ya tiene un NZBN — esto hace que el proceso de incorporación sea materialmente más sencillo que en jurisdicciones que requieren un número de registro independiente solo para la facturación electrónica.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Identifikatoren', '[["Routing-Kennung", "New Zealand Business Number (NZBN)"], ["Rolle", "Peppol-Teilnehmerkennung"]]', 'Jedes neuseeländische Unternehmen besitzt bereits eine NZBN — dies macht das Onboarding wesentlich einfacher als in Jurisdiktionen, die eine separate Registrierungsnummer nur für die E-Rechnungsstellung verlangen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiants', '[["Identifiant de routage", "New Zealand Business Number (NZBN)"], ["Rôle", "Identifiant de participant Peppol"]]', 'Chaque entreprise néo-zélandaise possède déjà un NZBN — cela rend l''intégration nettement plus simple que dans les juridictions exigeant un numéro d''enregistrement distinct uniquement pour la facturation électronique.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Alcance del mandato de 2027', '[["Se aplica a", "Facturas comerciales nacionales solo en NZD"], ["Excluye", "Proveedores internacionales, facturación transfronteriza"]]', 'Si su contrato con el gobierno de Nueva Zelanda implica algún elemento transfronterizo, verifique cuidadosamente si esa línea de factura específica está realmente dentro o fuera del alcance de este mandato.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Umfang des 2027-Mandats', '[["Gilt für", "Nur inländische Handelsrechnungen in NZD"], ["Ausgenommen", "Internationale Lieferanten, grenzüberschreitende Rechnungsstellung"]]', 'Wenn Ihr neuseeländischer Regierungsvertrag ein grenzüberschreitendes Element enthält, prüfen Sie sorgfältig, ob die betreffende Rechnungszeile tatsächlich innerhalb oder außerhalb des Anwendungsbereichs dieses Mandats liegt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Portée du mandat de 2027', '[["S''applique à", "Factures commerciales nationales en NZD uniquement"], ["Exclut", "Fournisseurs internationaux, facturation transfrontalière"]]', 'Si votre contrat avec le gouvernement néo-zélandais comporte un élément transfrontalier, vérifiez attentivement si cette ligne de facture spécifique relève ou non du champ d''application de ce mandat.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sin reporte en tiempo real', '[["Reporte fiscal", "El GST continúa mediante declaraciones periódicas"], ["Conservación", "7 años"]]', 'A diferencia de Irlanda o Francia, no existe una capa de reporte de datos añadida a este mandato — se trata puramente del formato de intercambio, no de la modernización de la administración fiscal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Keine Echtzeit-Meldung', '[["Steuermeldung", "GST läuft weiterhin über periodische Erklärungen"], ["Aufbewahrung", "7 Jahre"]]', 'Anders als in Irland oder Frankreich gibt es hier keine zusätzliche Datenmeldeebene — es geht rein um das Austauschformat, nicht um die Modernisierung der Steuerverwaltung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Pas de déclaration en temps réel', '[["Déclaration fiscale", "La GST continue via des déclarations périodiques"], ["Conservation", "7 ans"]]', 'Contrairement à l''Irlande ou à la France, il n''y a pas de couche de déclaration de données greffée sur ce mandat — il s''agit purement du format d''échange, pas de la modernisation de l''administration fiscale.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Gobernanza', '[["Autoridad Peppol nacional", "Ministerio de Negocios, Innovación y Empleo (MBIE)"], ["Función", "Supervisa el marco, acredita Puntos de Acceso"]]', 'El MBIE no opera una plataforma de compensación o intercambio en sí mismo — las facturas se mueven directamente entre Puntos de Acceso acreditados en la red Peppol.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Governance', '[["Nationale Peppol-Autorität", "Ministry of Business, Innovation and Employment (MBIE)"], ["Rolle", "Beaufsichtigt den Rahmen, akkreditiert Access Points"]]', 'Das MBIE betreibt selbst keine Clearing- oder Austauschplattform — Rechnungen bewegen sich direkt zwischen akkreditierten Access Points im Peppol-Netzwerk.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Gouvernance', '[["Autorité Peppol nationale", "Ministry of Business, Innovation and Employment (MBIE)"], ["Rôle", "Supervise le cadre, agrée les points d''accès"]]', 'Le MBIE n''exploite pas lui-même de plateforme de contrôle ou d''échange — les factures circulent directement entre points d''accès agréés sur le réseau Peppol.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Determinación del estatus de "gran proveedor"', '[["Umbral", "33 millones de NZD de facturación total"], ["Incluye", "Facturación de filiales combinada con la matriz"], ["Período de medición", "Cada uno de los dos períodos contables anteriores"]]', 'Compruebe esto sobre una base de grupo consolidada, no solo la facturación de su entidad independiente — una filial más pequeña de un grupo grande aún puede quedar sujeta al umbral.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Bestimmung des Status als "Großlieferant"', '[["Schwelle", "NZD 33 Millionen Gesamtumsatz"], ["Umfasst", "Tochterumsatz kombiniert mit Mutterunternehmen"], ["Messzeitraum", "Jeder der beiden vorangegangenen Rechnungszeiträume"]]', 'Prüfen Sie dies auf konsolidierter Konzernbasis, nicht nur anhand des Umsatzes Ihrer eigenständigen Einheit — eine kleinere Tochtergesellschaft eines großen Konzerns kann dennoch von der Schwelle erfasst werden.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Détermination du statut de « grand fournisseur »', '[["Seuil", "33 millions de NZD de chiffre d''affaires total"], ["Inclut", "Chiffre d''affaires des filiales combiné à celui de la société mère"], ["Période de mesure", "Chacune des deux périodes comptables précédentes"]]', 'Vérifiez cela sur une base de groupe consolidée, pas seulement le chiffre d''affaires de votre entité autonome — une filiale plus petite d''un grand groupe peut tout de même être visée par le seuil.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Obligaciones del lado del organismo', '[["Umbral de 2.000+ facturas", "Debe enviar Y recibir facturas electrónicas estructuradas"], ["Estándar de pago", "95% de las facturas electrónicas pagadas en 5 días hábiles"]]', 'El pago rápido es el incentivo tangible para los proveedores aquí — los organismos cubiertos por estas reglas están contractualmente motivados a preferir proveedores con facturación electrónica.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Behördenseitige Pflichten', '[["2.000+-Rechnungen-Schwelle", "Muss strukturierte E-Rechnungen senden UND empfangen können"], ["Zahlungsstandard", "95 % der E-Rechnungen innerhalb von 5 Geschäftstagen bezahlt"]]', 'Schnelle Zahlung ist hier der greifbare Anreiz für Lieferanten — von diesen Regeln erfasste Behörden sind vertraglich motiviert, e-rechnungsfähige Lieferanten zu bevorzugen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Obligations côté organisme', '[["Seuil de 2 000+ factures", "Doit envoyer ET recevoir des factures électroniques structurées"], ["Norme de paiement", "95 % des factures électroniques payées sous 5 jours ouvrables"]]', 'Le paiement rapide est ici l''incitation tangible pour les fournisseurs — les organismes couverts par ces règles sont contractuellement motivés à privilégier les fournisseurs pratiquant la facturation électronique.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Estilo de aplicación', '[["Sanciones financieras estatutarias", "Ninguna"], ["Mecanismo", "Administrativo, bajo las Reglas de Contratación Pública"], ["Transparencia", "Los organismos informan trimestralmente al MBIE; los resultados se publican públicamente"]]', 'No hay multa por incumplimiento — pero el reporte trimestral público sobre el rendimiento de pago rápido crea su propia presión reputacional sobre los organismos para cumplir.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Durchsetzungsstil', '[["Gesetzliche Geldstrafen", "Keine"], ["Mechanismus", "Administrativ, im Rahmen der Government Procurement Rules"], ["Transparenz", "Behörden berichten vierteljährlich an das MBIE; Ergebnisse werden öffentlich veröffentlicht"]]', 'Es gibt keine Geldstrafe für Nichteinhaltung — aber die öffentliche vierteljährliche Berichterstattung über die Zahlungspünktlichkeit erzeugt einen eigenen Reputationsdruck auf die Behörden zur Einhaltung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Style d''application', '[["Sanctions financières légales", "Aucune"], ["Mécanisme", "Administratif, dans le cadre des règles de passation des marchés publics"], ["Transparence", "Les organismes rendent compte trimestriellement au MBIE ; les résultats sont publiés publiquement"]]', 'Il n''y a pas d''amende en cas de non-conformité — mais le rapport trimestriel public sur la performance de paiement rapide crée sa propre pression réputationnelle sur les organismes pour s''y conformer.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Evalúe su estatus de tamaño', 'Confirme si la facturación combinada de su grupo (incluidas las filiales) supera los 33 millones de NZD en cada uno de los últimos dos períodos contables — esto determina si el mandato de enero de 2027 se aplica a usted.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bewerten Sie Ihren Größenstatus', 'Bestätigen Sie, ob der kombinierte Konzernumsatz (einschließlich Tochtergesellschaften) in jedem der letzten beiden Rechnungszeiträume NZD 33 Millionen übersteigt — dies bestimmt, ob das Mandat vom Januar 2027 für Sie gilt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Évaluez votre statut de taille', 'Confirmez si le chiffre d''affaires combiné de votre groupe (y compris les filiales) dépasse 33 millions de NZD au cours de chacune des deux dernières périodes comptables — cela détermine si le mandat de janvier 2027 s''applique à vous.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija una solución compatible con Peppol', 'Confirme que su software de facturación puede enviar y recibir facturas electrónicas Peppol de forma nativa, o explore opciones de integración con un Punto de Acceso certificado si no puede.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie eine Peppol-kompatible Lösung', 'Bestätigen Sie, dass Ihre Rechnungssoftware Peppol-E-Rechnungen nativ senden und empfangen kann, oder prüfen Sie Integrationsoptionen mit einem zertifizierten Access Point, falls nicht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez une solution compatible Peppol', 'Confirmez que votre logiciel de facturation peut envoyer et recevoir nativement des factures électroniques Peppol, ou explorez des options d''intégration avec un point d''accès certifié si ce n''est pas le cas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Valide específicamente contra PINT A-NZ', 'Asegúrese de que sus plantillas de facturación cumplan con los campos obligatorios y formatos de datos del estándar actual — el perfil heredado Peppol BIS 3.0 ya no se acepta en ninguna parte de la red.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Validieren Sie speziell gegen PINT A-NZ', 'Stellen Sie sicher, dass Ihre Rechnungsvorlagen die Pflichtfelder und Datenformate des aktuellen Standards erfüllen — das veraltete Peppol-BIS-3.0-Profil wird nirgendwo mehr im Netzwerk akzeptiert.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Validez spécifiquement par rapport à PINT A-NZ', 'Assurez-vous que vos modèles de facturation respectent les champs obligatoires et formats de données de la norme actuelle — l''ancien profil Peppol BIS 3.0 n''est plus accepté nulle part sur le réseau.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Realice pruebas con organismos gubernamentales durante 2026', 'Participe en pruebas con suficiente antelación al plazo de enero de 2027 para detectar problemas de incorporación antes de que se conviertan en presión de última hora.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie 2026 mit Regierungsbehörden', 'Nehmen Sie rechtzeitig vor der Frist im Januar 2027 an Tests teil, um Onboarding-Probleme zu erkennen, bevor sie zu Terminstress werden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez avec les organismes gouvernementaux au cours de 2026', 'Participez aux tests bien avant l''échéance de janvier 2027 pour détecter les problèmes d''intégration avant qu''ils ne deviennent une pression liée à l''échéance.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su NZBN está correctamente registrado', 'Este es su identificador de enrutamiento Peppol — asegúrese de que esté vinculado correctamente a su registro de Punto de Acceso.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihre NZBN korrekt registriert ist', 'Dies ist Ihre Peppol-Routing-Kennung — stellen Sie sicher, dass sie korrekt mit Ihrer Access-Point-Registrierung verknüpft ist.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que votre NZBN est correctement enregistré', 'Il s''agit de votre identifiant de routage Peppol — assurez-vous qu''il est correctement lié à votre enregistrement de point d''accès.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'New Zealand' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🇦🇺 Consistencia trans-Tasmania', NULL, NULL, 'Las organizaciones que operan tanto en Nueva Zelanda como en Australia pueden alinearse en torno a PINT A-NZ para reutilizar asignaciones y validaciones — un beneficio genuinamente práctico de la elección de especificación compartida entre ambos países.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🇦🇺 Trans-tasmanische Konsistenz', NULL, NULL, 'Organisationen, die sowohl in Neuseeland als auch in Australien tätig sind, können sich an PINT A-NZ ausrichten, um Mappings und Validierungen wiederzuverwenden — ein wirklich praktischer Vorteil der gemeinsamen Spezifikationswahl beider Länder.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🇦🇺 Cohérence trans-tasmanienne', NULL, NULL, 'Les organisations opérant à la fois en Nouvelle-Zélande et en Australie peuvent s''aligner sur PINT A-NZ pour réutiliser les mappages et validations — un avantage véritablement pratique du choix de spécification commun aux deux pays.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🏛️ Reglas de contratación, no legislación fiscal', NULL, NULL, 'Dado que todo este marco se sitúa dentro de las Reglas de Contratación Pública en lugar de la legislación del GST, la aplicación es administrativa y contractual — no existe un equivalente a un régimen sancionador de una autoridad fiscal aquí.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🏛️ Beschaffungsregeln, kein Steuerrecht', NULL, NULL, 'Da dieses gesamte Rahmenwerk innerhalb der Government Procurement Rules statt der GST-Gesetzgebung angesiedelt ist, erfolgt die Durchsetzung administrativ und vertraglich — ein Äquivalent zu einem Bußgeldregime einer Steuerbehörde gibt es hier nicht.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🏛️ Règles de passation de marchés, pas droit fiscal', NULL, NULL, 'Étant donné que ce cadre entier s''inscrit dans les règles de passation des marchés publics plutôt que dans la législation GST, l''application est administrative et contractuelle — il n''existe pas ici d''équivalent à un régime de sanctions d''une autorité fiscale.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📈 El B2B voluntario sigue siendo fomentado', NULL, NULL, 'Fuera de la cadena de suministro gubernamental, la adopción de la facturación electrónica es voluntaria pero se fomenta activamente — muchas empresas la adoptan de todos modos por la reducción de errores y el procesamiento más rápido que aporta.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📈 Freiwilliges B2B bleibt gefördert', NULL, NULL, 'Außerhalb der staatlichen Lieferkette ist die Einführung der E-Rechnungsstellung freiwillig, wird aber aktiv gefördert — viele Unternehmen führen sie trotzdem ein wegen der reduzierten Fehler und der schnelleren Verarbeitung, die sie mit sich bringt.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📈 Le B2B volontaire reste encouragé', NULL, NULL, 'En dehors de la chaîne d''approvisionnement gouvernementale, l''adoption de la facturation électronique est volontaire mais activement encouragée — de nombreuses entreprises l''adoptent tout de même pour la réduction des erreurs et le traitement plus rapide qu''elle apporte.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💰 Un alcance más estrecho, solo nacional', NULL, NULL, 'El mandato para grandes proveedores se aplica solo a facturas comerciales nacionales denominadas en NZD — un alcance deliberadamente estrecho en comparación con mandatos más ambiciosos en otras partes de este rastreador.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💰 Ein engerer, rein inländischer Geltungsbereich', NULL, NULL, 'Das Großlieferanten-Mandat gilt nur für in NZD denominierte inländische Handelsrechnungen — ein bewusst enger Geltungsbereich im Vergleich zu ambitionierteren Mandaten anderswo in diesem Tracker.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💰 Une portée plus étroite, uniquement nationale', NULL, NULL, 'Le mandat pour les grands fournisseurs ne s''applique qu''aux factures commerciales nationales libellées en NZD — une portée délibérément restreinte par rapport à des mandats plus ambitieux ailleurs dans ce tracker.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'New Zealand' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

